import{_ as a,o as d,c as t,a3 as o}from"./chunks/framework.B8xISX-C.js";const h=JSON.parse('{"title":"races","description":"","frontmatter":{},"headers":[],"relativePath":"reference/races.md","filePath":"reference/races.md"}'),s={name:"reference/races.md"};function r(l,e,c,i,n,f){return d(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="races" tabindex="-1">races <a class="header-anchor" href="#races" aria-label="Permalink to &quot;races&quot;">​</a></h1><p>A playable race: picks, government, homeworld, AI personality tables, text keys and art. A new race borrows a stock race&#39;s starting relations through <code>relationsAs</code>.</p><p>A mod adds records in <code>records/races/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;races&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>races</code>. Schema: <code>schemas/records/races.schema.json</code>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-schema" class="field-name"><code>$schema</code></span><a class="field-link" href="#f-schema" aria-label="Link to $schema">#</a></td><td>one of <code>carina-race/1</code></td><td>yes</td><td></td></tr><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-stock" class="field-name"><code>stock</code></span><a class="field-link" href="#f-stock" aria-label="Link to stock">#</a></td><td>true or false</td><td>yes</td><td></td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-singularKey" class="field-name"><code>singularKey</code></span><a class="field-link" href="#f-singularKey" aria-label="Link to singularKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-flavourKey" class="field-name"><code>flavourKey</code></span><a class="field-link" href="#f-flavourKey" aria-label="Link to flavourKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-homeStarKey" class="field-name"><code>homeStarKey</code></span><a class="field-link" href="#f-homeStarKey" aria-label="Link to homeStarKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-rulerNamesKey" class="field-name"><code>rulerNamesKey</code></span><a class="field-link" href="#f-rulerNamesKey" aria-label="Link to rulerNamesKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-government" class="field-name"><code>government</code></span><a class="field-link" href="#f-government" aria-label="Link to government">#</a></td><td>snake_case key</td><td>yes</td><td></td></tr><tr><td><span id="f-picks" class="field-name"><code>picks</code></span><a class="field-link" href="#f-picks" aria-label="Link to picks">#</a></td><td>list of snake_case key (no repeats)</td><td>yes</td><td></td></tr><tr><td><span id="f-homeworld" class="field-name"><code>homeworld</code></span><a class="field-link" href="#f-homeworld" aria-label="Link to homeworld">#</a></td><td>object (fields below)</td><td>yes</td><td></td></tr><tr><td><span id="f-homeworld.size" class="field-name"><code>homeworld.size</code></span><a class="field-link" href="#f-homeworld.size" aria-label="Link to homeworld.size">#</a></td><td>one of <code>medium</code>, <code>large</code></td><td>yes</td><td></td></tr><tr><td><span id="f-homeworld.climate" class="field-name"><code>homeworld.climate</code></span><a class="field-link" href="#f-homeworld.climate" aria-label="Link to homeworld.climate">#</a></td><td>one of <code>terran</code>, <code>ocean</code></td><td>yes</td><td></td></tr><tr><td><span id="f-homeworld.minerals" class="field-name"><code>homeworld.minerals</code></span><a class="field-link" href="#f-homeworld.minerals" aria-label="Link to homeworld.minerals">#</a></td><td>one of <code>abundant</code>, <code>rich</code></td><td>yes</td><td></td></tr><tr><td><span id="f-homeworld.gravity" class="field-name"><code>homeworld.gravity</code></span><a class="field-link" href="#f-homeworld.gravity" aria-label="Link to homeworld.gravity">#</a></td><td>one of <code>normal</code>, <code>low</code>, <code>heavy</code></td><td>yes</td><td></td></tr><tr><td><span id="f-homeworld.artifacts" class="field-name"><code>homeworld.artifacts</code></span><a class="field-link" href="#f-homeworld.artifacts" aria-label="Link to homeworld.artifacts">#</a></td><td>true or false</td><td>yes</td><td></td></tr><tr><td><span id="f-aiPersonality" class="field-name"><code>aiPersonality</code></span><a class="field-link" href="#f-aiPersonality" aria-label="Link to aiPersonality">#</a></td><td>list of exactly 10 one of <code>xenophobic</code>, <code>ruthless</code>, <code>aggressive</code>, <code>erratic</code>, <code>honorable</code>, <code>pacifist</code></td><td>yes</td><td></td></tr><tr><td><span id="f-variants" class="field-name"><code>variants</code></span><a class="field-link" href="#f-variants" aria-label="Link to variants">#</a></td><td>object (fields below)</td><td>yes</td><td></td></tr><tr><td><span id="f-variants.hard" class="field-name"><code>variants.hard</code></span><a class="field-link" href="#f-variants.hard" aria-label="Link to variants.hard">#</a></td><td>list of exactly 3 object (fields below)</td><td>yes</td><td></td></tr><tr><td><span id="f-variants.impossible" class="field-name"><code>variants.impossible</code></span><a class="field-link" href="#f-variants.impossible" aria-label="Link to variants.impossible">#</a></td><td>list of exactly 3 object (fields below)</td><td>yes</td><td></td></tr><tr><td><span id="f-roles" class="field-name"><code>roles</code></span><a class="field-link" href="#f-roles" aria-label="Link to roles">#</a></td><td>object (fields below)</td><td>no</td><td></td></tr><tr><td><span id="f-roles.portrait" class="field-name"><code>roles.portrait</code></span><a class="field-link" href="#f-roles.portrait" aria-label="Link to roles.portrait">#</a></td><td>asset role id</td><td>yes</td><td></td></tr><tr><td><span id="f-roles.selection" class="field-name"><code>roles.selection</code></span><a class="field-link" href="#f-roles.selection" aria-label="Link to roles.selection">#</a></td><td>asset role id</td><td>yes</td><td></td></tr><tr><td><span id="f-roles.ambassadorPortrait" class="field-name"><code>roles.ambassadorPortrait</code></span><a class="field-link" href="#f-roles.ambassadorPortrait" aria-label="Link to roles.ambassadorPortrait">#</a></td><td>asset role id</td><td>yes</td><td></td></tr><tr><td><span id="f-roles.emblem" class="field-name"><code>roles.emblem</code></span><a class="field-link" href="#f-roles.emblem" aria-label="Link to roles.emblem">#</a></td><td>asset role id</td><td>yes</td><td></td></tr><tr><td><span id="f-roles.ambassadorRoom" class="field-name"><code>roles.ambassadorRoom</code></span><a class="field-link" href="#f-roles.ambassadorRoom" aria-label="Link to roles.ambassadorRoom">#</a></td><td>asset role id</td><td>yes</td><td></td></tr><tr><td><span id="f-roles.musicCue" class="field-name"><code>roles.musicCue</code></span><a class="field-link" href="#f-roles.musicCue" aria-label="Link to roles.musicCue">#</a></td><td>asset role id</td><td>yes</td><td></td></tr><tr><td><span id="f-relationsAs" class="field-name"><code>relationsAs</code></span><a class="field-link" href="#f-relationsAs" aria-label="Link to relationsAs">#</a></td><td>snake_case key or null</td><td>no</td><td></td></tr><tr><td><span id="f-defaultRulerSex" class="field-name"><code>defaultRulerSex</code></span><a class="field-link" href="#f-defaultRulerSex" aria-label="Link to defaultRulerSex">#</a></td><td>one of <code>male</code>, <code>female</code></td><td>no</td><td></td></tr></tbody></table><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><ul><li>profile <code>availableRaces</code> (an <code>append</code> row on catalog <code>profile</code>, key <code>steam-dos-140b23</code>), so computer players can draw it at New Game</li><li><code>assets/roles.json</code> <code>races</code>: <code>{ &quot;race&quot;: &quot;&lt;your race key&gt;&quot;, &quot;artBase&quot;: &quot;&lt;stock race key&gt;&quot; }</code>; every picture of the stock race stands in for one the mod does not bring</li></ul><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>Computer players play a new race fully: its personality and objective weights are race data.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>A mod race is on the paged Select Race screen (in the demo build under the custom-race terms: Small galaxy only).</li><li>A new race needs its text keys in the mod&#39;s English text.</li><li>Each race record carries <code>&quot;$schema&quot;: &quot;carina-race/1&quot;</code> inside the <code>records</code> list of its records file.</li><li><code>roles</code> is optional and not used by the game; leave it out. The race&#39;s pictures come from <code>assets/roles.json</code>.</li><li>Own pictures replace the art base&#39;s per role, at the same size: <code>races.portrait.select.&lt;your race key&gt;</code> and so on.</li><li>Non-stock races have at most 10 pick points.</li><li>A race either names an <code>artBase</code> (every role it leaves out is aliased to the base race&#39;s) or names none and then supplies the whole art contract (Hollow Choir does). A race with neither is refused <code>race-art-missing</code>, one issue listing every missing role.</li><li>The contract is one role per family member of the stock races: the select, diplomacy and ambassador portraits, the select background, the two emblems, the council medallions, the ambassador scene, the research director, the six hulls of combat and picture atlases, <code>colony.pop</code>, the colonist figures, the spy and the trooper, plus <code>music.race.&lt;your race key&gt;</code> (Ogg and an m4a twin, at most 300 s). The other-sex portrait, ambassador and director (<code>-female</code>, or <code>-male</code> for a female-default race) are optional.</li><li>Colonist figure atlases are 26x49 with frames <code>colony.&lt;job&gt;</code> (0,0,22,26) and <code>list.&lt;job&gt;</code> (0,27,26,22); the spy is a 17x23 image and the trooper 192x288.</li><li>A mod race ships exactly one portrait per sex; the numbered variants (<code>.2</code> to <code>.4</code>) are the stock Humans&#39; and are refused (<code>role-namespace</code>).</li><li>In play a mod race&#39;s ships draw its own <code>shipsai.*</code> atlases and its audience plays <code>music.race.&lt;your race key&gt;</code> (a race with an art base plays the base race&#39;s theme).</li></ul><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>$schema</code>, <code>aiPersonality</code>, <code>defaultRulerSex</code>, <code>flavourKey</code>, <code>government</code>, <code>homeStarKey</code>, <code>homeworld</code>, <code>homeworld.artifacts</code>, <code>homeworld.climate</code>, <code>homeworld.gravity</code>, <code>homeworld.minerals</code>, <code>homeworld.size</code>, <code>nameKey</code>, <code>picks</code>, <code>relationsAs</code>, <code>roles</code>, <code>roles.ambassadorPortrait</code>, <code>roles.ambassadorRoom</code>, <code>roles.emblem</code>, <code>roles.musicCue</code>, <code>roles.portrait</code>, <code>roles.selection</code>, <code>rulerNamesKey</code>, <code>singularKey</code>, <code>stock</code>, <code>variants</code>, <code>variants.hard</code>, <code>variants.impossible</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: <code>aiPersonality</code>, <code>picks</code>, <code>variants.hard</code>, <code>variants.impossible</code></li></ul>',15)])])}const p=a(s,[["render",r]]);export{h as __pageData,p as default};
